import logging
import threading
from ..exceptions import ProhibitedInstanceError, DataTransferVerificationFailure
from .dt_definition import DataTransferDefinition
from ..utils.param_checker import tput_user_value2normalized
from ..config import loggers as ute_ue_logging


PLUGINS_WHERE_SIMULTANEOUS_DT_IMPLEMENTED = [
    "taf.ue.plugin.rtg",
    "taf.ue.plugin.prisma",
    "ta_ue_plugin_rtg",
]


class LteDataTransfer:
    """Object responsible for managing data transfer."""
    def __init__(self, name, dt_definition, configuration, logger_name='ute_ue'):
        """
        Basic initialization.

        :param name: name assigned to DataTransfer object
        :param dt_definition: DataTransferDefinition object - definition of data transfer characteristics
        :param configuration: tool dependant configuration provided by UE instance needed for data transfer operations
        """
        self.name = name
        if self.__class__.__name__ == 'LteDataTransfer':
            raise ProhibitedInstanceError("you can't create instance of DataTransfer base class, use derived ones")
        if not isinstance(dt_definition, DataTransferDefinition):
            raise TypeError(f'dt_definition should be an instance of DataTransferDefinition,\ndt_definition: {dt_definition}')
        self._dt_definition = dt_definition
        self._configuration = configuration
        self._stop_timer = None
        if 'ue_logger_name' in self._configuration:
            # TODO: search usages - should be removed?
            raw_logger = logging.getLogger(self._configuration['ue_logger_name'])
        else:
            raw_logger = logging.getLogger(logger_name)
        self.logger = ute_ue_logging.LoggerAdapter4EmptyExtra(raw_logger, {'area': 'DATATRANSFER'})

        if self._uses_legacy_direction_param():
            implemented_in_plugin = any(plugin in self.__module__
                                        for plugin in PLUGINS_WHERE_SIMULTANEOUS_DT_IMPLEMENTED)
            if implemented_in_plugin:
                self.logger.warning("You are using deprecated direction parameter "
                                    "'simultaneous_ul_dl' in iperf datatransfer. Deprecated since December 2023")
            else:
                raise NotImplementedError("You are using not implemented option 'simultaneous_ul_dl' "
                                          "for data transfer direction. This option is not being implemented.")

    def __str__(self):
        dt_info = f"{self.__class__.__name__} '{self.name}'"
        return dt_info

    @property
    def direction(self):
        """Direction of data transfer ('ul', 'dl' or 'simultaneous_ul_dl')"""
        return self._dt_definition.direction

    @property
    def app_server(self):
        """App Server configuration info"""
        dt_config = getattr(self, 'dt_config') if hasattr(self, 'dt_config') else None
        return dt_config.get('app_server') if dt_config else {}

    def start(self):
        """
        Start data transfer with parameters defined in dt_definition passed during initialization.

        :return: None
        """
        raise NotImplementedError

    def stop(self):
        """
        Stop already running data transfer.

        Fires exception if given data transfer (selected by it's name) was not started yet.
        No action if given data transfer is already finished.
        :return: None
        """
        raise NotImplementedError

    def await_finish(self):
        """
        Wait until this data transfer finish.

        Fires exception if given data transfer (selected by it's name) was not started yet.
        No action if given data transfer is already finished.
        :return: None
        """
        raise NotImplementedError

    def is_running(self):
        """
        Check if data transfer is running

        :return: boolean
        """
        raise NotImplementedError

    def check_data_transfer(self):
        """
        Check if data transfer client and server output is progressing
        :param validation_period: time for validation
        :param validation_interval: time for the maximum time when client and server outs are different
        :return:
        """
        raise NotImplementedError

    def get_definition(self):
        """
        Get data transfer definition passed during initialization.

        :return: data_transfer_definition instance
        """
        return self._dt_definition

    def verify_average_throughput_with_deviation(self, tput, deviation, omit=0, end=0, tput_collection_src="iperf"):
        """
        Verify if average throughput is in desired range: tput-(tput*deviation) <-> tput+(tput*deviation)

        If data transfer direction is 'simultaneous_ul_dl' then you can set different tput expectations
        for each direction. You do it using 'extended' format like: 'ul:19Mbits/sec,dl:75Mbits/sec'.
        If you don't use 'extended' format then check like tput='20Mbits/sec' means expect around 20Mbits/sec on both 'ul' and 'dl'.

        Same applies to deviation

        :param tput: desired average data transfer throughput in string format. e.g. '10Mbits/sec', 'ul:19Mbits/sec,dl:75Mbits/sec'
        :param deviation: acceptable deviation (expressed in percentages) from desired data transfer throughput. e.g '5%', 'ul:5%,dl:2%'
        :param end: it is end time in seconds to stop counting the tput
               ex. '40' - it takes into account data till 40 second of transfer.:param omit:
               it is a delay in seconds to start counting the tput ex. '20' - 1st 20 seconds of datatransfer will be omitted.
        :param tput_collection_src: source for collecting throughput data
        :return: None
        :raises DataTransferVerificationFailure: if verification fails
        """
        if self.direction == "simultaneous_ul_dl":
            ul_tput = DataTransferDefinition.extract_throughput_string(tput, direction='ul')
            ul_deviation = self.extract_deviation_string(deviation, direction='ul')
            dl_tput = DataTransferDefinition.extract_throughput_string(tput, direction='dl')
            dl_deviation = self.extract_deviation_string(deviation, direction='dl')
            avr_tputs = self.get_average_throughput(omit, end, tput_collection_src=tput_collection_src)
            self._verify_average_throughput_with_deviation(ul_tput, ul_deviation, 'ul', avr_tputs['ul'])
            self._verify_average_throughput_with_deviation(dl_tput, dl_deviation, 'dl', avr_tputs['dl'])
        else:
            average_throughput = self.get_average_throughput_with_params(omit, end, tput_collection_src=tput_collection_src)
            self._verify_average_throughput_with_deviation(tput, deviation, self.direction, average_throughput)

    def _verify_average_throughput_with_deviation(self, expected_throughput, deviation, direction, average_throughput):
        self.logger.info(f'{self}: average {direction} throughput = {average_throughput} Kbits/sec')
        deviation_as_float = self._parse_deviation(deviation)
        normalized_tput = tput_user_value2normalized(expected_throughput)
        min_threshold = normalized_tput - (normalized_tput * deviation_as_float)
        max_threshold = normalized_tput + (normalized_tput * deviation_as_float)
        if average_throughput < min_threshold or average_throughput > max_threshold:
            msg = f'\nBased on values provided: tput={normalized_tput} [kbits/s], deviation={deviation}\n' \
                  f'Expected tput range: min={min_threshold} [kbits/sec] <-> max={max_threshold} [kbits/sec]\n' \
                  f'Actual average tput={average_throughput} [kbits/sec]'
            raise DataTransferVerificationFailure(msg)

    @staticmethod
    def extract_deviation_string(deviation, direction):
        """
        Extract throughput deviation requested per given direction

        Traffic may be either single direction or bi-directional.
        If expected throughput deviation is given as '5%'
        it means such value for single direction traffic
        or it means same expected value for bi-directional traffic.
        But for bi-directional traffic throughput deviation may have form
        'ul:5%,dl:2%' which sets different expectations for
        different directions.

        :param throughput: string (ul/dl values may differ)
        :param direction: 'ul' or 'dl'
        :return: throughput string per given direction
        """
        if ('ul:' in deviation) and ('dl:' in deviation) and (',' in deviation):
            # ul:4%,dl:2%
            # dl:3%,ul:3.5%
            if deviation.startswith('ul:'):
                ul_deviation_str, dl_deviation_str = deviation.split(',', 1)
            else:
                dl_deviation_str, ul_deviation_str = deviation.split(',', 1)
            if (not ul_deviation_str.startswith('ul:')) or (not dl_deviation_str.startswith('dl:')):
                example_deviation = 'ul:5%,dl:2%'
                raise ValueError(f"Invalid throughput deviation string: '{deviation}' - should be like '{example_deviation}'")
            ul_deviation_str = ul_deviation_str[3:]
            dl_deviation_str = dl_deviation_str[3:]
            return ul_deviation_str if direction == 'ul' else dl_deviation_str
        else:
            return deviation

    def verify_throughput_with_datagram_loss(self, max_allowed_datagram_loss):
        """
        :param max_allowed_datagram_loss: max acceptable datagram loss in percentage ex. '5%'
        :return:
        """
        datagram_loss = self.get_datagram_loss()
        max_allowed_datagram_loss = self._parse_datagram_loss(max_allowed_datagram_loss)

        if datagram_loss > max_allowed_datagram_loss:
            msg = f'Datagram loss ({datagram_loss}%) is higher than maximum allowed value ({max_allowed_datagram_loss}%)'
            raise DataTransferVerificationFailure(msg)

    def verify_average_throughput(self, tput_min, tput_max=None, omit=0, end=0, tput_collection_src="iperf"):
        """
        Verify if running throughput is in desired range: tput_min <-> tput_max
        If tput_max=None: Verify if running throughput is above desired threshold: tput_min

        If data transfer direction is 'simultaneous_ul_dl' then you can set different tput_min expectations
        for each direction. You do it using 'extended' format like: 'ul:19Mbits/sec,dl:75Mbits/sec'.
        If you don't use 'extended' format then check like tput_min='20Mbits/sec' means expect at least 20Mbits/sec on both 'ul' and 'dl'.

        Same applies to tput_max

        :param tput_min: lower threshold in string format. e.g. '10Mbits/sec', 'ul:19Mbits/sec,dl:75Mbits/sec'
        :param tput_max: upper threshold in string format. e.g. '20Mbits/sec', 'ul:49Mbits/sec,dl:95Mbits/sec'
        :param omit: it is a delay in seconds to start counting the tput ex. '20' - 1st 20 seconds of datatransfer will be omitted.
        :param end: it is end time in seconds to stop counting the tput ex. '40' - it takes into account data till 40 second of transfer.
        :param tput_collection_src: source for collecting throughput data
        :return: None
        :raises DataTransferVerificationFailure: if verification fails
        """
        if self.direction == "simultaneous_ul_dl":
            ul_tput_min = DataTransferDefinition.extract_throughput_string(tput_min, direction='ul')
            ul_tput_max = DataTransferDefinition.extract_throughput_string(tput_max, direction='ul')
            dl_tput_min = DataTransferDefinition.extract_throughput_string(tput_min, direction='dl')
            dl_tput_max = DataTransferDefinition.extract_throughput_string(tput_max, direction='dl')
            avr_tputs = self.get_average_throughput(omit, end, tput_collection_src=tput_collection_src)
            self._verify_average_throughput(ul_tput_min, ul_tput_max, 'ul', avr_tputs['ul'])
            self._verify_average_throughput(dl_tput_min, dl_tput_max, 'dl', avr_tputs['dl'])
        else:
            average_throughput = self.get_average_throughput_with_params(omit, end, tput_collection_src)
            self._verify_average_throughput(tput_min, tput_max, self.direction, average_throughput)

    def get_average_throughput_with_params(self, omit, end, tput_collection_src, format=None):
        if omit or end or tput_collection_src != "iperf" or format:
            return self.get_average_throughput(omit, end, tput_collection_src=tput_collection_src, format=format)
        return self.get_average_throughput()

    def _verify_average_throughput(self, tput_min, tput_max, direction, average_throughput):
        self.logger.info(f'{self}: average {direction} throughput = {average_throughput} Kbits/sec')
        normalized_tput_min = tput_user_value2normalized(tput_min)
        if average_throughput < normalized_tput_min:
            msg = f'Expected tput_min={normalized_tput_min} [kbits/s] \n' \
                  f'Actual average tput={average_throughput} [kbits/sec]'
            raise DataTransferVerificationFailure(msg)
        if tput_max and average_throughput > tput_user_value2normalized(tput_max):
            msg = f'Expected tput_min={normalized_tput_min} [kbits/s] \n' \
                  f'Expected tput_max={tput_user_value2normalized(tput_max)} [kbits/s] \n' \
                  f'Actual average tput={average_throughput} [kbits/sec]'
            raise DataTransferVerificationFailure(msg)

    def _uses_legacy_direction_param(self):
        return self._dt_definition.direction.lower() == "simultaneous_ul_dl"

    def reset_statistics(self):
        """
        Reset data transfer statistics on UE.

        :return: None
        :raises: :py:class:`ute_ue.exceptions.UeProcedureError`: If reset data transfer statistics failed
        """
        raise NotImplementedError

    def get_data_transfer_statistics(self, omit=0, end=0, **kwargs):
        """
        Get all statistics of data transfer (intermediate results on timeline & final result)
        :param omit: it is a delay in seconds to start counting the tput ex. '20' - 1st 20 seconds of datatransfer will be omitted.
        :param end: it is end time in seconds to stop counting the tput ex. '40' - it takes into account data till 40 second of transfer.
        :return: data transfer statistics.
        """
        raise NotImplementedError

    def get_average_throughput(self, omit=0, end=0, tput_collection_src="iperf", format=None):
        """
        Abstract method for getting average throughput of data transfer.
        Average throughput is measured from 'dt.start()' to current time or from 'dt.start()' to 'dt.stop()' if data transfer is already finished
        :param omit: it is a delay in seconds to start counting the tput ex. '20' - 1st 20 seconds of datatransfer will be omitted.
        :param end: it is end time in seconds to stop counting the tput ex. '40' - it takes into account data till 40 second of transfer.
        :param tput_collection_src: source for collecting throughput data
        :param format: format of unit of return value (Available 'k' - default kbits, 'm' - mbits, 'g' - gbits)
        :return: avr throughput in unit: Kbits/sec; If data transfer is simultaneous_ul_dl then return {'dl': dl_avr_tput, 'ul': ul_avr_tput}
        """
        raise NotImplementedError

    def get_datagram_loss(self):
        """
        Getting datagram loss of UDP data transfer
        :return: value of datagram loss in %
        """
        raise NotImplementedError

    def _parse_deviation(self, unparsed_deviation):
        number = unparsed_deviation.rstrip('%')
        deviation = float(number) / 100.0
        return deviation

    def _parse_datagram_loss(self, unparsed_datagram_loss):
        number = unparsed_datagram_loss.rstrip('%')
        datagram_loss_percent = float(number)
        return datagram_loss_percent

    def _start_stop_timer(self, wait_time):
        """
        Method creates the timer that expires after wait time and calls stop method from the instance.

        It can be used after data transfer has been started succesfully.

        Usage example in ue specific implementation::

            def start():
                ...
                if not self._dt_definition.has_default_duration():
                    self._start_stop_timer(self._dt_definition.duration)
            ...
            def stop():
                if self._stop_timer:
                    self._stop_timer.cancel()

        :param wait_time: Wait time for the timer, value in seconds
        :return: None
        """
        self.logger.debug(f'_stop_timer started for {self}, it expires after {wait_time}s')
        self._stop_timer = threading.Timer(wait_time, self.stop)
        self._stop_timer.start()
